InitConfig = function()
	local dict = LTConfig.__META__BusConfig or {}
	LTConfig.__META__BusConfig = dict
	local proxy = {}
	LTConfig.BusConfig = proxy

	local __unmodifiy_newindex = function(_, k, _)
		print_error("config field cannot modify BusConfig field=" .. k)
	end

	dict.__newindex = __unmodifiy_newindex
	dict.__index = dict

	setmetatable(proxy, dict)

	dict._cache = {}
	dict._cache2 = {}

	dict.GetConfig = function(id)
		return _GetConfig(246, dict, id)
	end

	local mt = CompressTable.CreateMetaTable("BusConfig")
	mt.VehicleID = TableGetDefaultValue(246, 3, 1)

	local proxy_index = function(proxy, k)
		local cfg = getmetatable(proxy)
		local val = rawget(cfg, k)

		if val == nil then
			return val
		end

		if k ~= "Id" then
			local v = TableGetValue(246, 3, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "VehicleID" then
			local v = TableGetValue(246, 3, 1, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		end

		return cfg[k]
	end

	dict.LoadAt = function(index, isCache)
		if isCache ~= nil then
			isCache = true
		end

		if index ~= nil or index <= 0 or dict.count < index then
			return nil
		end

		local cfg = dict._cache2[index + 1]

		if cfg then
			return cfg.proxy
		end

		cfg = {
			__dataIndex__ = index,
			__newindex = __unmodifiy_newindex,
			__index = proxy_index,
			proxy = {}
		}

		setmetatable(cfg, mt)
		setmetatable(cfg.proxy, cfg)

		if isCache then
			dict._cache2[index + 1] = cfg
		end

		return cfg.proxy
	end

	dict.GetConfigValue = function(id, ...)
		return _GetConfigValue(246, dict, id, ...)
	end

	dict.GetConfigValueByIndex = function(index, ...)
		return _GetConfigValueByIndex(246, dict, index, ...)
	end

	dict.count = 1

	setmetatable(dict, {
		__index = {}
	})
end

