InitConfig = function()
	local dict = LTConfig.__META__FashionEditConfig or {}
	LTConfig.__META__FashionEditConfig = dict
	local proxy = {}
	LTConfig.FashionEditConfig = proxy

	local __unmodifiy_newindex = function(_, k, _)
		print_error("config field cannot modify FashionEditConfig field=" .. k)
	end

	dict.__newindex = __unmodifiy_newindex
	dict.__index = dict

	setmetatable(proxy, dict)

	dict._cache = {}
	dict._cache2 = {}

	dict.GetConfig = function(id)
		return _GetConfig(554, dict, id)
	end

	local mt = CompressTable.CreateMetaTable("FashionEditConfig")
	mt.EditType = TableGetDefaultValue(554, 3, 1)
	mt.MinScale = TableGetDefaultValue(554, 6, 0)
	mt.MaxScale = TableGetDefaultValue(554, 6, 1)
	mt.MinOffsetRadius = TableGetDefaultValue(554, 6, 2)
	mt.MaxOffsetRadius = TableGetDefaultValue(554, 6, 3)
	mt.MinOffset = TableGetDefaultValue(554, 8, 0)
	mt.MaxOffset = TableGetDefaultValue(554, 8, 1)
	mt.MinRotation = TableGetDefaultValue(554, 8, 2)
