InitConfig = function()
	local dict = LTConfig.__META__KTVConfig or {}
	LTConfig.__META__KTVConfig = dict
	local proxy = {}
	LTConfig.KTVConfig = proxy

	local __unmodifiy_newindex = function(_, k, _)
		print_error("config field cannot modify KTVConfig field=" .. k)
	end

	dict.__newindex = __unmodifiy_newindex
	dict.__index = dict

	setmetatable(proxy, dict)

	dict._cache = {}
	dict._cache2 = {}

	dict.GetConfig = function(id)
		return _GetConfig(842, dict, id)
	end

	local mt = CompressTable.CreateMetaTable("KTVConfig")
	mt.SongName = TableGetDefaultValue(842, 7, 0)
	mt.SImage = TableGetDefaultValue(842, 7, 1)
	mt.SingerFightSpiritID = TableGetDefaultValue(842, 10, 0)
	mt.isInvite = TableGetDefaultValue(842, 1, 0)
	mt.__IDX__Artist = TableGetDefaultValue(842, 3, 1)
	mt.__RAW__Artist = TableGetDefaultValue(842, 7, 2)
