InitConfig = function()
	local dict = LTConfig.__META__MessageDescriptionConfig or {}
	LTConfig.__META__MessageDescriptionConfig = dict
	local proxy = {}
	LTConfig.MessageDescriptionConfig = proxy

	local __unmodifiy_newindex = function(_, k, _)
