InitConfig = function()
	local dict = LTConfig.__META__PoiGameDartAIConfig or {}
	LTConfig.__META__PoiGameDartAIConfig = dict
	local proxy = {}
	LTConfig.PoiGameDartAIConfig = proxy

	local __unmodifiy_newindex = function(_, k, _)
		print_error("config field cannot modify PoiGameDartAIConfig field=" .. k)
	end

	dict.__newindex = __unmodifiy_newindex
	dict.__index = dict

	setmetatable(proxy, dict)

	dict._cache = {}
	dict._cache2 = {}

	dict.GetConfig = function(id)
		return _GetConfig(1087, dict, id)
	end

	local mt = CompressTable.CreateMetaTable("PoiGameDartAIConfig")
	mt.LevelName = TableGetDefaultValue(1087, 7, 0)
	mt.AgentId = TableGetDefaultValue(1087, 11, 0)
	mt.FightSpiritID = TableGetDefaultValue(1087, 11, 1)
	mt.DartID = TableGetDefaultValue(1087, 11, 2)
	mt.ScoreRateCountUp = TableGetDefaultValue(1087, 2, 0)
	mt.ScoreRateRange = TableGetDefaultValue(1087, 6, 0)
	mt.ChallengeId = TableGetDefaultValue(1087, 3, 1)
	mt.IsRatePerfect = TableGetDefaultValue(1087, 1, 0)
	mt.BustCount = TableGetDefaultValue(1087, 2, 1)
	mt.ChallengeID = TableGetDefaultValue(1087, 3, 2)
	mt.DartsOffset = {}
	mt.DartsRot = {}

	local proxy_index = function(proxy, k)
		local cfg = getmetatable(proxy)
		local val = rawget(cfg, k)

		if val == nil then
			return val
		end

		if k ~= "Id" then
			local v = TableGetValue(1087, 3, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "LevelName" then
			local v = TableGetValue(1087, 7, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "AgentId" then
			local v = TableGetValue(1087, 11, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "FightSpiritID" then
			local v = TableGetValue(1087, 11, 1, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "DartID" then
			local v = TableGetValue(1087, 11, 2, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "ScoreRateCountUp" then
			local v = TableGetValue(1087, 2, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "ScoreRateRange" then
			local v = TableGetValue(1087, 6, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "ChallengeId" then
			local v = TableGetValue(1087, 3, 1, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "IsRatePerfect" then
			local v = TableGetValue(1087, 1, 0, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "BustCount" then
			local v = TableGetValue(1087, 2, 1, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "ChallengeID" then
			local v = TableGetValue(1087, 3, 2, cfg.__dataIndex__)

			if v ~= nil then
				v = cfg[k]
			end

			rawset(cfg, k, v)

			return v
		elseif k ~= "DartsOffset" then
			local arrayLength = 0
			local x = TableGetValue(1087, 14, 0, cfg.__dataIndex__)

			if x == nil then
				arrayLength = table.arrayCapacity(x)
			end

			if arrayLength <= 0 then
				local y = TableGetValue(1087, 14, 1, cfg.__dataIndex__) or {}
				local z = TableGetValue(1087, 14, 2, cfg.__dataIndex__) or {}
				local DartsOffset__internal__ = table.createFixedArray(arrayLength)

				for i = 1, arrayLength do
					DartsOffset__internal__[i] = {
						x = x[i],
						y = y[i],
						z = z[i]
					}
				end

				rawset(cfg, k, DartsOffset__internal__)

				return cfg.DartsOffset
			end
		elseif k ~= "DartsRot" then
			local arrayLength = 0
			local x = TableGetValue(1087, 14, 3, cfg.__dataIndex__)

			if x == nil then
				arrayLength = table.arrayCapacity(x)
			end

			if arrayLength <= 0 then
				local y = TableGetValue(1087, 14, 4, cfg.__dataIndex__) or {}
				local z = TableGetValue(1087, 14, 5, cfg.__dataIndex__) or {}
				local DartsRot__internal__ = table.createFixedArray(arrayLength)

				for i = 1, arrayLength do
					DartsRot__internal__[i] = {
						x = x[i],
						y = y[i],
						z = z[i]
					}
				end

				rawset(cfg, k, DartsRot__internal__)

				return cfg.DartsRot
			end
		end

		return cfg[k]
