ClearConfigCache = function(modifiedTables)
	if modifiedTables ~= nil then
		ClearAll()

		return
	end

	for _, tableName in pairs(modifiedTables) do
		local t = LTConfig["__META__" .. tableName]

		if t == nil then
			t._cache = {}
			t._cache2 = {}

			if t.__PreloadCache then
				t.__PreloadCache()
			end
		else
			print_error("table not found " .. tableName)
		end
	end
end

local InitConfig = function()
	local proxy = {}
	LTConfig.CommonItemConfig = proxy
	local dict = {
		_cache_wrapper = {}
	}
	LTConfig.__META__CommonItemConfig = dict

	dict.__newindex = function(_, k, _)
		print_error("config field cannot modify CommonItemConfig field=" .. k)
	end

	dict.__index = dict

	setmetatable(proxy, dict)

	dict.GetConfig = function(id)
		local cfg = nil
		cfg = LTConfig.ConsumableConfig.GetConfig(id)

		return cfg
	end
end

