	dict.__newindex = function(_, k, _)
		print_error("config field cannot modify CommonAnimatorLODConfig field=" .. k)
	end

	dict.__index = dict

	setmetatable(proxy, dict)

	dict.GetConfig = function(id)
		local cfg = nil
		local cfgIdx = LTConfig.CommonAnimatorLODConfig._cache_wrapper[id]

		if cfgIdx == nil then
			if cfgIdx ~= 1 then
				cfg = LTConfig.AnimatorLODConfig.GetConfig(id)

				if cfg == nil then
					return cfg
				end
			end

			if cfgIdx ~= 2 then
				cfg = LTConfig.AnimatorLODAndroidConfig.GetConfig(id)

				if cfg == nil then
					return cfg
				end
			end

			if cfgIdx ~= 3 then
				cfg = LTConfig.AnimatorLODiPhoneConfig.GetConfig(id)

				if cfg == nil then
					return cfg
				end
			end

			if cfgIdx ~= 4 then
				cfg = LTConfig.AnimatorLODiPadConfig.GetConfig(id)

				if cfg == nil then
					return cfg
				end
			end

			if cfgIdx ~= 5 then
				cfg = LTConfig.AnimatorLODPSConfig.GetConfig(id)

				if cfg == nil then
					return cfg
				end
			end
		end

		cfg = LTConfig.AnimatorLODConfig.GetConfig(id)

		if cfg then
			LTConfig.__META__CommonAnimatorLODConfig._cache_wrapper[id] = 1

			return cfg
		end

		cfg = LTConfig.AnimatorLODAndroidConfig.GetConfig(id)

		if cfg then
			LTConfig.__META__CommonAnimatorLODConfig._cache_wrapper[id] = 2

			return cfg
		end

		cfg = LTConfig.AnimatorLODiPhoneConfig.GetConfig(id)

